try{
 foreach([0,1] as $tenant){$backup[$tenant]=S::table('setting')->where('tenant_id',$tenant)->find();$settings=S::settings($tenant);unset($settings['enabled']);$settings['apps']=array_values(array_unique(array_merge($settings['apps'],['aigc_llm'])));$settings['tool_budgets']['aigc_llm']['POST tasks']=['user'=>200,'tenant'=>200];$settings['tool_budgets']['aigc_llm']['POST stream']=['user'=>200,'tenant'=>200];$settings['rpm']=max(30,$settings['rpm']);$values=['enabled'=>1,'config'=>S::encode($settings),'update_time'=>time()];if($backup[$tenant])S::table('setting')->where('tenant_id',$tenant)->update($values);else S::table('setting')->insert($values+['tenant_id'=>$tenant,'create_time'=>time()]);}
