 $params=['model_code'=>'DeepSeek-V4-Pro','prompt'=>'Reply OK.','max_tokens'=>16,'enable_thinking'=>false];
 foreach(['tasks','stream'] as $suffix){$values=C::validate(['code'=>$run.'.tool.'.$suffix,'method'=>'POST','path'=>'/api/v1/tools/aigc_llm/'.$suffix,'kind'=>'tool','config'=>['title'=>'Local paid text tool acceptance','role'=>'submit','input'=>$schema,'example'=>$params,'responses'=>['200'=>['description'=>'Native tool response']]]]);$ids[]=S::table('contract')->insertGetId($values+['version'=>1,'status'=>'draft']+S::timestamp());}
 $call=function(array $params,string $idem,string $path,string $method='POST')use($key,&$previewHeaders){$h=curl_init('http://127.0.0.1:19874'.$path.($method==='GET'&&$params?'?'.http_build_query($params):''));curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>210,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key['key'],'Content-Type: application/json','Idempotency-Key: '.$idem]+($method==='POST'&&isset($previewHeaders[$path])?['X-Open-Contract-Preview: '.$previewHeaders[$path]]:[])]]);if($method==='POST')curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>S::encode($params)]);$body=curl_exec($h);$status=curl_getinfo($h,CURLINFO_HTTP_CODE);$error=curl_errno($h);curl_close($h);verify($error===0,'Local preview connection failed; do not resubmit uncertain calls');return ['status'=>$status,'body'=>$body];};
 foreach([false,true] as $stream){$spent=(float)S::table('request')->where('key_id',$key['id'])->sum('actual_user')+(float)S::table('request')->where(['key_id'=>$key['id'],'active'=>1])->sum('budget_user');$params=['model_code'=>'DeepSeek-V4-Pro','prompt'=>'Reply OK.','max_tokens'=>16,'enable_thinking'=>false];verify($priorSpent+$spent+200<=1000,'Authorized total budget exhausted');$path='/api/v1/tools/aigc_llm/'.($stream?'stream':'tasks');$ticket=app\common\service\open_platform\OpenContractPreview::issue($ids[$stream?1:0],$key['id']);$previewHeaders[$path]=$ticket['preview_token'];$idem=$ticket['idempotency_key'];$wire=$call($params,$idem,$path);$row=S::owner('request',1,1)->where(['key_id'=>$key['id'],'idempotency_hash'=>hash('sha256','POST '.$path.' '.$idem)])->find();verify($row!==null,'Gateway rejected before tracked admission (HTTP '.$wire['status'].'): '.substr($wire['body'],0,300));
