 verify($wire['status']===200&&$row['status']==='success'&&$row['billing_status']==='settled','Real call did not finish with trusted usage: '.S::encode($entry));verify(isset($data['usage']['total_tokens']),'Trusted upstream usage missing');
 $consumptionIds=S::json($row['consumption_ids']);verify(count($consumptionIds)===1,'Native tool did not associate exactly one consumption');$consumption=Db::name('ai_consumption_log')->where(['id'=>$consumptionIds[0],'tenant_id'=>1,'user_id'=>1])->find();verify($consumption&&$consumption['billing_status']==='settled','Native consumption not settled');$source=$consumption['consume_no'];$userLogs=Db::name('user_account_log')->where(['tenant_id'=>1,'user_id'=>1])->where('source_sn',$source)->select()->toArray();$tenantLogs=Db::name('tenant_point_log')->where('tenant_id',1)->where('source_sn',$source)->select()->toArray();verify((float)$consumption['actual_user_price']===(float)$row['actual_user'],'Consumption and API charge disagree');$net=function($logs){$n=0.;foreach($logs as $l)$n+=((int)$l['action']===2?1:-1)*(float)$l['change_amount'];return round($n,2);};verify($net($userLogs)===(float)$row['actual_user'],'User ledger disagrees with actual charge');verify($net($tenantLogs)===(float)$row['actual_tenant'],'Tenant ledger disagrees with cost');$replay=$call($params,$idem,$path);verify($replay===$wire,'Idempotent response changed');verify(S::owner('request',1,1)->where(['key_id'=>$key['id'],'idempotency_hash'=>hash('sha256','POST '.$path.' '.$idem)])->count()===1,'Replay created another request');verify(Db::name('user_account_log')->where(['tenant_id'=>1,'user_id'=>1])->where('source_sn',$source)->count()===count($userLogs),'Replay charged again');verify(isset($data['task_id'])&&str_starts_with($data['task_id'],'ot_aigc_llm_'),'Stable text task ID missing');$taskWire=$call([],'','/api/v1/tools/aigc_llm/tasks/'.$data['task_id'],'GET');$taskData=S::json($taskWire['body'])['data']??[];verify($taskWire['status']===200&&($taskData['content']??null)===($data['content']??null)&&($taskData['status']??'')==='success','Owned native text task query changed known output');foreach(['tasks','results'] as $read){$readWire=$call([],'','/api/v1/tools/aigc_llm/'.$read,'GET');$listed=S